import subprocess,shutil,os
ESB=os.environ.get('ESBUILD','')   # optional: path to esbuild for tighter minifying; a built-in minifier is used when unset
def esb(src,loader):
    if not os.path.exists(ESB): return None
    r=subprocess.run([ESB,'--minify','--target=es2020','--loader='+loader],input=src,capture_output=True,text=True)
    return r.stdout.strip() if r.returncode==0 and r.stdout.strip() else None
def mincss(c):
    out=esb(c,'css')
    if out: return out
    return mincss_basic(c)
def mincss_basic(c):
    c=re.sub(r'/\*.*?\*/','',c,flags=re.S)
    c=re.sub(r'\s*([{};,>])\s*',r'\1',c)
    c=re.sub(r':\s+',':',c)
    c=re.sub(r'\s+',' ',c)
    return c.strip()
def minjs(j):
    out=esb(j,'js')
    if out: return out
    return minjs_basic(j)
def minjs_basic(j):
    out=[]
    for line in j.split('\n'):
        t=line.strip()
        if not t or t.startswith('//'): continue
        out.append(t)
    return '\n'.join(out)

def item(time,title,text,cls=''):
    c=('item '+cls).strip()
    return f'<div class="{c}"><div class="time">{time}</div><div><h3>{title}</h3><p>{text}</p></div></div>'
